typedef struct { uint32_t no, po; int64_t modified, created, size; } Entry;
typedef struct { Entry *e; char *arena; uint32_t n; size_t arena_len; } Projection;
typedef struct { uint32_t id; int score; } Hit;

static double now_ms(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec*1000.0+t.tv_nsec/1e6; }
static void die(sqlite3 *db, const char *m) { fprintf(stderr,"%s: %s\n",m,db?sqlite3_errmsg(db):""); exit(2); }
static void execsql(sqlite3 *db,const char*s){char*e=0;if(sqlite3_exec(db,s,0,0,&e)!=SQLITE_OK){fprintf(stderr,"sql: %s\n",e);sqlite3_free(e);exit(2);}}
static long rss_kb(void){struct rusage r;getrusage(RUSAGE_SELF,&r);return r.ru_maxrss/1024;}
static long current_rss_kb(void){mach_task_basic_info_data_t i;mach_msg_type_number_t n=MACH_TASK_BASIC_INFO_COUNT;if(task_info(mach_task_self(),MACH_TASK_BASIC_INFO,(task_info_t)&i,&n)!=KERN_SUCCESS)return 0;return (long)(i.resident_size/1024);}
static long fsize(const char*p){struct stat s;return stat(p,&s)?0:s.st_size;}
static const char *dirs[]={"Users/alex/Documents","Users/alex/Downloads","Users/alex/Library/Application Support","Users/alex/Projects/everyfile/src","Applications","Users/alex/Pictures/Trips/上海","Users/alex/.config","Library/Developer/Xcode/DerivedData"};
static const char *stems[]={"report","invoice","important","screenshot","archive","meeting-notes","source","design","résumé","ångström","strasse","readme","package","database","presentation","budget"};
static const char *exts[]={"pdf","txt","md","rs","swift","json","jpg","png","zip","docx","app","sqlite"};
static void strings(uint32_t i,char*n,size_t nc,char*p,size_t pc){
  const char *stem=stems[(i*7)%16],*ext=exts[(i*11)%12],*dir=dirs[(i*13)%8];
  if(i%97==0) snprintf(n,nc,".%s-%06u.%s",stem,i,ext); else if(i%113==0) snprintf(n,nc,"Q3 %s final copy %06u.%s",stem,i,ext); else snprintf(n,nc,"%s-%06u.%s",stem,i,ext);
  snprintf(p,pc,"/%s/%s",dir,n);
}
static void bindrow(sqlite3_stmt*s,uint32_t i,const char*n,const char*p){
 sqlite3_bind_int(s,1,(int)i+1);sqlite3_bind_text(s,2,n,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,p,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,4,1700000000+(i%2000000));sqlite3_bind_int64(s,5,1600000000+(i%3000000));sqlite3_bind_int64(s,6,128+(i*7919u)%50000000);if(sqlite3_step(s)!=SQLITE_DONE)die(sqlite3_db_handle(s),"insert");sqlite3_reset(s);sqlite3_clear_bindings(s);
}
static double build(sqlite3*db,uint32_t n,const char*bin){
 double t=now_ms(); execsql(db,"PRAGMA journal_mode=WAL;PRAGMA synchronous=NORMAL;DROP TABLE IF EXISTS files;DROP TABLE IF EXISTS search;CREATE TABLE files(id INTEGER PRIMARY KEY,name_norm TEXT NOT NULL,path_norm TEXT NOT NULL,modified INTEGER,created INTEGER,size INTEGER);CREATE VIRTUAL TABLE search USING fts5(name_norm,path_norm,content='files',content_rowid='id',tokenize='trigram');BEGIN");
 sqlite3_stmt*s=0;if(sqlite3_prepare_v2(db,"INSERT INTO files VALUES(?,?,?,?,?,?)",-1,&s,0)!=SQLITE_OK)die(db,"prepare");
 FILE*f=fopen(bin,"wb");uint64_t arena=0;fwrite(&n,4,1,f);fwrite(&arena,8,1,f);Entry z={0};for(uint32_t i=0;i<n;i++)fwrite(&z,sizeof z,1,f);
 char name[160],path[512];Entry*ents=calloc(n,sizeof*ents);
 for(uint32_t i=0;i<n;i++){strings(i,name,sizeof name,path,sizeof path);bindrow(s,i,name,path);ents[i].no=(uint32_t)arena;fwrite(name,1,strlen(name)+1,f);arena+=strlen(name)+1;ents[i].po=(uint32_t)arena;fwrite(path,1,strlen(path)+1,f);arena+=strlen(path)+1;ents[i].modified=1700000000+(i%2000000);ents[i].created=1600000000+(i%3000000);ents[i].size=128+(i*7919u)%50000000;}
 sqlite3_finalize(s);execsql(db,"COMMIT;INSERT INTO search(search) VALUES('rebuild');PRAGMA wal_checkpoint(TRUNCATE)");fseek(f,4,SEEK_SET);fwrite(&arena,8,1,f);fwrite(ents,sizeof*ents,n,f);fclose(f);free(ents);return now_ms()-t;
}
static Projection loadp(const char*bin,double*load_ms){double t=now_ms();FILE*f=fopen(bin,"rb");Projection p={0};uint64_t al;fread(&p.n,4,1,f);fread(&al,8,1,f);p.arena_len=(size_t)al;p.e=malloc((size_t)p.n*sizeof* p.e);p.arena=malloc(p.arena_len);fread(p.e,sizeof*p.e,p.n,f);fread(p.arena,1,p.arena_len,f);fclose(f);*load_ms=now_ms()-t;return p;}
static int sort_mode=0;static Projection*sort_p=0;
static int cmp(const void*a,const void*b){const Hit*x=a,*y=b;const Entry*ex=&sort_p->e[x->id],*ey=&sort_p->e[y->id];int c=0;if(sort_mode==0)c=y->score-x->score;else if(sort_mode==1)c=strcmp(sort_p->arena+ex->no,sort_p->arena+ey->no);else if(sort_mode==2)c=strcmp(sort_p->arena+ex->po,sort_p->arena+ey->po);else if(sort_mode==3)c=(ex->modified<ey->modified)-(ex->modified>ey->modified);else if(sort_mode==4)c=(ex->created<ey->created)-(ex->created>ey->created);else c=(ex->size<ey->size)-(ex->size>ey->size);return c?c:(x->id>y->id)-(x->id<y->id);}
static int terms(const char*s,const char*q){char b[128];snprintf(b,sizeof b,"%s",q);char*t=strtok(b," ");while(t){if(!strstr(s,t))return 0;t=strtok(NULL," ");}return 1;}
static size_t memquery(Projection*p,const char*q,int first,int sm){Hit*h=first?0:malloc((size_t)p->n*sizeof* h);size_t k=0;for(uint32_t i=0;i<p->n;i++){const char*n=p->arena+p->e[i].no,*pa=p->arena+p->e[i].po;if(terms(n,q)||terms(pa,q)){k++;if(first&&sm==0)return 1;if(!first)h[k-1]=(Hit){i,strstr(n,q)?100:10};}}if(!first){sort_mode=sm;sort_p=p;qsort(h,k,sizeof* h,cmp);free(h);}return k;}
static size_t ftsquery(sqlite3*db,Projection*p,const char*q,int first,int hybrid,int sm){sqlite3_stmt*s=0;const char*sql="SELECT rowid FROM search WHERE search MATCH ? ORDER BY rank";if(sqlite3_prepare_v2(db,sql,-1,&s,0)!=SQLITE_OK)die(db,"fts prepare");char expr[160]={0};char tmp[128];snprintf(tmp,sizeof tmp,"%s",q);char*t=strtok(tmp," ");while(t){if(*expr)strcat(expr," AND ");strcat(expr,"\"");strcat(expr,t);strcat(expr,"\"");t=strtok(NULL," ");}sqlite3_bind_text(s,1,expr,-1,SQLITE_TRANSIENT);size_t k=0,cap=1024;int needsort=hybrid&&sm!=0;Hit*h=hybrid&&(!first||needsort)?malloc(cap*sizeof*h):0;while(sqlite3_step(s)==SQLITE_ROW){uint32_t id=(uint32_t)sqlite3_column_int(s,0)-1;k++;if(h){if(k>cap){cap*=2;h=realloc(h,cap*sizeof*h);}h[k-1]=(Hit){id,100};}if(first&&!needsort)break;}sqlite3_finalize(s);if(h){sort_mode=sm;sort_p=p;qsort(h,k,sizeof*h,cmp);free(h);}return k;}
static double median(double*a){for(int i=0;i<5;i++)for(int j=i+1;j<5;j++)if(a[j]<a[i]){double t=a[i];a[i]=a[j];a[j]=t;}return a[2];}
static void querycsv(FILE*out,sqlite3*db,Projection*p,const char*engine,const char*ca,const char*q,int sm){double a[5],b[5];size_t k=0;int ishybrid=!strcmp(engine,"hybrid"),usefts=!strcmp(engine,"fts5")||(ishybrid&&strlen(q)>=3);if(usefts)ftsquery(db,p,q,0,ishybrid,sm);else memquery(p,q,0,sm);for(int i=0;i<5;i++){double t=now_ms();if(usefts)ftsquery(db,p,q,1,ishybrid,sm);else memquery(p,q,1,sm);a[i]=now_ms()-t;t=now_ms();k=usefts?ftsquery(db,p,q,0,ishybrid,sm):memquery(p,q,0,sm);b[i]=now_ms()-t;}const char*sn[]={"relevance","name","path","modified","created","size"};fprintf(out,"%s,query,%s,%s,%zu,%s,%zu,%.3f,%.3f,,\n",engine,ca,q,strlen(q),sn[sm],k,median(a),median(b));}
static void updatecsv(FILE*out,sqlite3*db,Projection*p,int start,int count){sqlite3_stmt*del=0,*upd=0,*ins=0;sqlite3_prepare_v2(db,"INSERT INTO search(search,rowid,name_norm,path_norm) VALUES('delete',?,?,?)",-1,&del,0);sqlite3_prepare_v2(db,"UPDATE files SET name_norm=?,path_norm=?,modified=modified+1 WHERE id=?",-1,&upd,0);sqlite3_prepare_v2(db,"INSERT INTO search(rowid,name_norm,path_norm) VALUES(?,?,?)",-1,&ins,0);double t=now_ms();execsql(db,"BEGIN");char oldn[160],oldp[512],newn[160],newp[512];for(int x=0;x<count;x++){int i=start+x;strings((uint32_t)i,oldn,sizeof oldn,oldp,sizeof oldp);snprintf(newn,sizeof newn,"%s",oldn);snprintf(newp,sizeof newp,"%s",oldp);newn[0]=newn[0]=='x'?'y':'x';char*last=strrchr(newp,'/');if(last&&last[1])last[1]=newn[0];int id=i+1;sqlite3_bind_int(del,1,id);sqlite3_bind_text(del,2,oldn,-1,SQLITE_TRANSIENT);sqlite3_bind_text(del,3,oldp,-1,SQLITE_TRANSIENT);if(sqlite3_step(del)!=SQLITE_DONE)die(db,"fts delete");sqlite3_reset(del);sqlite3_clear_bindings(del);sqlite3_bind_text(upd,1,newn,-1,SQLITE_TRANSIENT);sqlite3_bind_text(upd,2,newp,-1,SQLITE_TRANSIENT);sqlite3_bind_int(upd,3,id);if(sqlite3_step(upd)!=SQLITE_DONE)die(db,"file update");sqlite3_reset(upd);sqlite3_clear_bindings(upd);sqlite3_bind_int(ins,1,id);sqlite3_bind_text(ins,2,newn,-1,SQLITE_TRANSIENT);sqlite3_bind_text(ins,3,newp,-1,SQLITE_TRANSIENT);if(sqlite3_step(ins)!=SQLITE_DONE)die(db,"fts insert");sqlite3_reset(ins);sqlite3_clear_bindings(ins);}sqlite3_finalize(del);sqlite3_finalize(upd);sqlite3_finalize(ins);execsql(db,"COMMIT");fprintf(out,"sqlite+fts5,update,batch-%d,,,relevance,%d,,%.3f,,,transactional searchable updates\n",count,count,now_ms()-t);t=now_ms();for(int x=0;x<count;x++){int i=start+x;char*n=p->arena+p->e[i].no,*pa=p->arena+p->e[i].po;n[0]=n[0]=='x'?'y':'x';char*last=strrchr(pa,'/');if(last&&last[1])last[1]=n[0];p->e[i].modified++;}fprintf(out,"memory,update,batch-%d,,,relevance,%d,,%.3f,,,in-place cache updates after transaction\n",count,count,now_ms()-t);}
int main(int ac,char**av){if(ac!=5){fprintf(stderr,"usage: bench rows db projection csv\n");return 2;}uint32_t n=(uint32_t)strtoul(av[1],0,10);remove(av[2]);remove(av[3]);sqlite3*db=0;if(sqlite3_open(av[2],&db)!=SQLITE_OK)die(db,"open");double bt=build(db,n,av[3]);double st=now_ms();sqlite3_stmt*s=0;sqlite3_prepare_v2(db,"SELECT count(*) FROM files",-1,&s,0);sqlite3_step(s);sqlite3_finalize(s);double startup=now_ms()-st,load_ms=0;Projection p=loadp(av[3],&load_ms);FILE*out=fopen(av[4],"w");fprintf(out,"engine,metric,case,query,query_len,sort,matches,first_ms,full_ms,value,unit,note\n");fprintf(out,"meta,build_time,,,,,,,,%.3f,ms,SQLite plus FTS5 plus projection\n",bt);fprintf(out,"meta,sqlite_startup,,,,,,,,%.3f,ms,warm open and count\n",startup);fprintf(out,"meta,projection_load,,,,,,,,%.3f,ms,read two contiguous arrays\n",load_ms);fprintf(out,"meta,sqlite_disk,,,,,,,,%ld,bytes,checkpointed database\n",fsize(av[2]));fprintf(out,"meta,projection_disk,,,,,,,,%ld,bytes,fixed records plus string arena\n",fsize(av[3]));fprintf(out,"meta,process_current_rss,,,,,,,,%ld,KiB,resident set after loading projection\n",current_rss_kb());fprintf(out,"meta,process_peak_rss,,,,,,,,%ld,KiB,conservative upper bound including build\n",rss_kb());
 const char*cs[]={"one-char","two-char","substring","multi-term","unicode","case-normalized"};const char*qs[]={"r","re","port","report pdf","résumé","readme"};
 for(int e=0;e<3;e++){const char*en=e==0?"memory":e==1?"fts5":"hybrid";for(int i=0;i<6;i++){if(e==1&&strlen(qs[i])<3)continue;querycsv(out,db,&p,en,cs[i],qs[i],i==3?3:0);}}
 for(int sm=1;sm<6;sm++){querycsv(out,db,&p,"memory","selectable-sort","report",sm);querycsv(out,db,&p,"hybrid","selectable-sort","report",sm);}
 updatecsv(out,db,&p,0,1);updatecsv(out,db,&p,1,100);updatecsv(out,db,&p,101,10000);fclose(out);free(p.e);free(p.arena);sqlite3_close(db);return 0;}
